41	const PROCESSING_FEE = 5;
42	const FIRST_INSURANCE_SURCHARGE = 0.1;
43	
44	const BASE_PREMIUMS: Record<string, number> = {
45	  sword: 100,
46	  amulet: 60,
47	};
48	
49	const quote = (step: QuoteStep): StepResult => {
50	  const base = step.items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
51	  return { premium: base + base * FIRST_INSURANCE_SURCHARGE + PROCESSING_FEE };
52	};
53	
54	export const runScenario = (scenario: Scenario): ScenarioResult => ({
55	  results: scenario.steps.map((step) => quote(step as QuoteStep)),
56	});
